mapper.select:
select t.id,t.name,t.code,t.type, t.full_name fullName, t.card_type cardType, t.id_card idCard, t.contact_name contactName, t.contact_tel contactTel, t.auth_user_count authUserCount, t.expiration_date expirationDate, t.status, t.remark, r.id roleId, r.name roleName from sys_tenant t left join sys_tenant_role tr on t.id = tr.tenant_id left join sys_role r on tr.role_id = r.id where t.
AND t.name LIKE #{rNameLike}
AND t.code LIKE #{rCodeLike}
AND t.id_card LIKE #{rCardLike}
AND t.contact_name LIKE #{rCNameLike}

mapper.update:
WITH SORTED_USERS AS (
    SELECT ID
    FROM SYS_USER
    WHERE TENANT_ID = #{tid}
    ORDER BY UTC_MODIFY DESC


            LIMIT 18446744073709551615 OFFSET #{count}


            OFFSET #{count} ROWS


)
UPDATE SYS_USER
    JOIN SORTED_USERS ON SYS_USER.ID = SORTED_USERS.ID
SET SYS_USER.FROZEN = #{frz}
WHERE SYS_USER.FROZEN IS NULL OR SYS_USER.FROZEN != 1
